use crate::{bq045 as b,model::*,rules::*,unit_support::*};
fn hunt(source:&str,token:&str,target:&str)->Action{Action{card_id:Some(source.into()),ability_id:Some(b::HUNT.into()),target_id:Some(target.into()),cost_selected:Some(vec![token.into()]),..Action::new("activate")}}
fn setup()->(Game,String,String,String){let mut g=game();fund(&mut g,0,"JC069",5);let source=field(&mut g,b::ID,0);let token=field(&mut g,"TK010",0);let target=field(&mut g,"JC125",2);g.board_mut(&target).unwrap().lock_markers=1;(g,source,token,target)}
#[test]fn bq045_original_gray_loyalty_blue_cube_is_core_not_loyalty(){assert_current_serial_catalog();let d=crate::catalog::card(b::ID);assert_eq!(d.loyalty,["灰色"]);assert_eq!(d.cost,3);assert_eq!(d.subtitle.as_deref(),Some("修格斯"));assert!(!d.supported);assert_eq!(d.defense,Some(1));assert!(d.unique);}
#[test]fn bq045_actual_paid_hunt_exhausts_one_token_before_response_then_gains_honor(){let(mut g,s,t,v)=setup();let before=g.resources(0);act(&mut g,0,hunt(&s,&t,&v));assert_eq!(g.resources(0),before-2);assert!(g.board(&t).unwrap().1.exhausted);assert!(g.board(&v).is_some());assert_eq!(g.players[0].honor,0);top(&mut g);assert!(g.board(&v).is_none());assert_eq!(g.players[0].honor,1);restore(&mut g);}
#[test]fn bq045_bad_cost_and_unlocked_targets_reject_atomically(){for mode in 0..6{let(mut g,s,t,v)=setup();let mut a=hunt(&s,&t,&v);match mode{0=>g.board_mut(&t).unwrap().exhausted=true,1=>g.board_mut(&t).unwrap().controller=1,2=>g.board_mut(&t).unwrap().face_down=true,3=>a.cost_selected=Some(vec![t.clone(),t.clone()]),4=>g.board_mut(&v).unwrap().lock_markers=0,_=>a.region=Some(0)}reject(&mut g,0,a);}let(mut g,s,_,_)=setup();reject(&mut g,0,Action{card_id:Some(s),ability_id:Some("bq045-core".into()),..Action::new("activate")});}
#[test]fn bq045_response_target_change_or_shield_prevents_destroy_and_honor_without_refund(){for mode in 0..3{let(mut g,s,t,v)=setup();act(&mut g,0,hunt(&s,&t,&v));match mode{0=>g.board_mut(&v).unwrap().lock_markers=0,1=>{g.hide_in_place(&v);},_=>g.board_mut(&v).unwrap().shield=1}top(&mut g);assert_eq!(g.players[0].honor,0);assert!(g.board(&t).unwrap().1.exhausted);if mode==2{assert_eq!(g.board(&v).unwrap().1.shield,0);}restore(&mut g);}}
#[test]fn bq045_paid_receipt_or_program_corruption_rejects_game_and_room(){let(mut g,s,t,v)=setup();act(&mut g,0,hunt(&s,&t,&v));for n in 0..5{let mut bad=g.clone();let f=bad.stack.last_mut().unwrap().frame.as_mut().unwrap();match n{0=>f.already_paid.clear(),1=>f.steps.swap(0,1),2=>f.targets[0].spec.predicate=None,3=>if let PaidCost::BQ045Exhausted(p)=&mut f.already_paid[1]{p.card.exhausted=true;},_=>f.source.card.definition="JC125".into()};assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());let mut room=crate::jc029_tests::envelope(&g);room.game=bad;assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).is_err());}}
fn core(parked:bool)->(Game,String){let mut g=game();g.players[0].society_zone.card=Some(g.make_card("MSBQ02",0));let c=g.make_card(b::ID,0);let id=c.id.clone();g.core_zones.push(crate::core_zone::CoreZone{owner:0,definition:b::ID.into(),card:if parked{Some(c.clone())}else{None},rest:0});if !parked{g.regions[0].cards.push(c);}fund(&mut g,0,"JC069",7);fund(&mut g,0,"JC042",1);(g,id)}
fn finish(g:&mut Game){for _ in 0..96{if let Some(p)=&g.pending{let id=p.choice.options[0].id.clone();choose(g,vec![id]);}else if g.stack.is_empty()&&g.effects.is_empty(){return;}else{pass(g);}}panic!("unfinished core");}
#[test]fn bq045_core_paid_command_from_both_zones_locks_and_represses_with_no_extra_fee(){for parked in [false,true]{let(mut g,_)=core(parked);let v=field(&mut g,"JC125",2);g.regions[0].influence[2/2]=2;let spell=held(&mut g,"BQ048",0);let money=g.resources(0);act(&mut g,0,Action{card_id:Some(spell),option:Some("core".into()),..Action::new("play")});for _ in 0..32{if g.pending.is_some(){break;}pass(&mut g);}assert_eq!(g.pending.as_ref().unwrap().choice.kind,"bq045-core-target");choose(&mut g,vec![v.clone()]);assert_eq!(g.board(&v).unwrap().1.lock_markers,1);finish(&mut g);assert_eq!(g.regions[0].influence[1],1);assert_eq!(g.resources(0),money-1);assert_eq!(g.players[0].honor,0);restore(&mut g);}}
#[test]fn bq045_two_core_invocations_keep_separate_choices_and_resume_final_repress(){let(mut g,_)=core(true);let v=field(&mut g,"JC125",2);g.regions[0].influence[1]=4;let spell=held(&mut g,"BQ063",0);act(&mut g,0,Action{card_id:Some(spell),option:Some("core".into()),..Action::new("play")});let mut targets=0;for _ in 0..96{if let Some(p)=&g.pending{if p.choice.kind=="bq045-core-target"{targets+=1;choose(&mut g,vec![v.clone()]);}else{let id=p.choice.options[0].id.clone();choose(&mut g,vec![id]);}}else if g.stack.is_empty()&&g.effects.is_empty(){break;}else{pass(&mut g);}}assert_eq!(targets,2);assert_eq!(g.board(&v).unwrap().1.lock_markers,2);assert_eq!(g.regions[0].influence[1],1);restore(&mut g);}
#[test]fn bq045_core_pending_snapshot_rejects_wrong_core_parent_duplicate_and_options(){let(mut g,_)=core(true);field(&mut g,"JC125",2);let spell=held(&mut g,"BQ048",0);act(&mut g,0,Action{card_id:Some(spell),option:Some("core".into()),..Action::new("play")});for _ in 0..32{if g.pending.is_some(){break;}pass(&mut g);}for n in 0..4{let mut bad=g.clone();let p=bad.pending.as_mut().unwrap();if let ChoiceResolution::Frame{frame,choice:FrameChoice::BQ045Core(c)}=&mut p.resolution{match n{0=>c.core.card.definition="BQ046".into(),1=>frame.source.card.definition="JC001".into(),2=>bad.effects.push_back(Effect::Frame{frame:frame.clone()}),_=>p.choice.options.clear()}}else{panic!("missing core continuation");}assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());let mut room=crate::jc029_tests::envelope(&g);room.game=bad;assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).is_err());}}
#[test]fn bq045_real_core_deploy_adds_one_forced_shield_and_hand_conceal_reveal_works(){let(mut g,id)=core(true);act(&mut g,0,Action{card_id:Some(id),region:Some(0),..Action::new("deploy")});finish(&mut g);let id=g.regions[0].cards.iter().find(|c|c.definition==b::ID).unwrap().id.clone();assert_eq!(g.board(&id).unwrap().1.shield,1);g.hide_in_place(&id);let hidden=g.regions[0].cards.iter().find(|c|c.definition==b::ID).unwrap().id.clone();act(&mut g,0,Action{card_id:Some(hidden),..Action::new("reveal")});finish(&mut g);assert_eq!(g.regions[0].cards.iter().find(|c|c.definition==b::ID).unwrap().shield,1);restore(&mut g);}
#[test]fn bq045_core_shield_cancels_only_that_invocation_and_own_core_can_receive_lock(){
 for self_target in [false,true]{let(mut g,id)=core(false);let v=if self_target{id}else{let v=field(&mut g,"JC125",2);g.board_mut(&v).unwrap().shield=1;v};g.regions[0].influence[1]=3;let spell=held(&mut g,"BQ063",0);act(&mut g,0,Action{card_id:Some(spell),option:Some("core".into()),..Action::new("play")});
 for _ in 0..96{if let Some(p)=&g.pending{let id=if p.choice.kind=="bq045-core-target"{v.clone()}else{p.choice.options[0].id.clone()};choose(&mut g,vec![id]);}else if g.stack.is_empty()&&g.effects.is_empty(){break;}else{pass(&mut g);}}
 assert_eq!(g.board(&v).unwrap().1.lock_markers,if self_target{2}else{1});assert_eq!(g.regions[0].influence[1],if self_target{0}else{1});restore(&mut g);
 }
}
fn trace_finish(t:&mut crate::abi112_review_play_tests::Trace,target:&str){for _ in 0..128{if let Some(p)=&t.room.game.pending{let id=if p.choice.kind=="bq045-core-target"{target.to_string()}else{p.choice.options[0].id.clone()};t.choose(vec![id]);}else if t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){return;}else{t.pass();}}panic!("unfinished trace");}
fn trace_value(t:crate::abi112_review_play_tests::Trace)->serde_json::Value{let mut v=t.value();for s in v["steps"].as_array_mut().unwrap(){let room=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=room.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.outcome,"rejected");assert_eq!(d.state,s["expected"]["state"]);assert!(!d.changed&&d.journal.is_empty());s["duplicate"]=serde_json::to_value(d).unwrap();}v}
fn natural()->serde_json::Value{
 use crate::{catalog,deck};use crate::abi112_review_play_tests::Trace;
 fn construct(seed:u64)->(Game,deck::DeckDraft){let mut d=deck::preset("watchers").unwrap();d.id="bq045-closed-50-plus-core".into();d.name="赫卡忒与触手命令".into();d.description="50普通牌和独立核心；非官方预组".into();d.society_id=Some("MSBQ02".into());d.core_card_id=Some(b::ID.into());d.cards=[("BQ064",3),("BQ048",3),("BQ050",3),("BQ063",3),("BQ052",3),("JC125",35)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();assert!(deck::validate(d.clone()).is_err());let mut cards=catalog::catalog().cards.clone();for c in &mut cards{if [b::ID,"BQ048","BQ050","BQ063","BQ052"].contains(&c.id.as_str()){c.supported=true;}}let mut societies=catalog::catalog().societies.clone();societies.iter_mut().find(|s|s.card.id=="MSBQ02").unwrap().card.supported=true;let d=deck::validate_with_registry(d,&cards,&societies).unwrap();let mut other=deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("bq045-natural".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for seat in 1..4{g.join(format!("P{seat}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d.clone(),other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();(g,d)}
 let(seed,g,deck)=(1..4097).map(|seed|seed*1_000_003).find_map(|seed|{let(g,d)=construct(seed);let h=&g.players[0].hand;(h.iter().filter(|c|c.definition=="BQ052").count()>=2&&h.iter().any(|c|c.definition=="BQ048")&&h.iter().any(|c|catalog::card(&c.definition).color=="灰")).then_some((seed,g,d))}).expect("bounded real shuffled opening");
 let mut t=Trace::new_preserving_rng(g,"bq045-natural-generation-core-lock-paid-hunt".into(),694);let mut hunted=false;let mut done=false;
 for _ in 0..2400{
  if hunted&&t.room.game.pending.is_none()&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){done=true;break;}
  if let Some(p)=t.room.game.pending.clone(){
   if p.choice.kind=="investigation"{let ids=p.choice.options.iter().map(|o|o.id.clone()).collect();t.action(p.seat,Action{choice_id:Some(p.choice.id),top:Some(ids),bottom:Some(vec![]),..Action::new("choose")});}
   else if p.choice.kind=="bq045-core-target"{let id=p.choice.options.iter().find(|o|t.room.game.board(&o.id).is_some_and(|(_,c)|c.controller==2&&c.definition=="JC125")).expect("real opponent character").id.clone();t.choose(vec![id]);}
   else if let ChoiceResolution::JC035PreparationOrder{declarations}=&p.resolution{let id=declarations.iter().find(|d|d.source.card.definition=="BQ052").unwrap().source.card.id.clone();t.choose(vec![id]);}
   else{t.choose(p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());}continue;
  }
  let g=&t.room.game;let legal=g.legal_actions(0);let enemy=g.regions.iter().flat_map(|r|&r.cards).find(|c|c.controller==2&&c.definition=="JC125");
  let hunt=legal.iter().find(|a|a.action.ability_id.as_deref()==Some(b::HUNT));
  let assets=legal.iter().find(|a|a.action.kind=="asset"&&g.players[0].hand.iter().find(|c|a.action.card_id.as_deref()==Some(&c.id)).is_some_and(|c|{let col=&catalog::card(&c.definition).color;let spare=!matches!(c.definition.as_str(),"BQ052"|"BQ048")||g.players[0].hand.iter().filter(|h|h.definition==c.definition).count()>1;spare&&if !g.loyalty(0,"BQ052"){col=="红"}else if !g.loyalty(0,b::ID){col=="灰"}else{g.players[0].assets.len()<5}}));
  let book=legal.iter().find(|a|a.action.kind=="play"&&!g.attachments.iter().any(|a|a.card.definition=="BQ052")&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="BQ052")));
  let deploy=legal.iter().find(|a|a.action.kind=="deploy"&&g.core_zones[0].card.as_ref().is_some_and(|c|a.action.card_id.as_deref()==Some(&c.id)));
  let command=legal.iter().find(|a|a.action.kind=="play"&&a.action.option.as_deref()==Some("core")&&enemy.is_some_and(|c|c.lock_markers==0)&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="BQ048")));
  if let Some(a)=hunt.or(assets).or(book).or(deploy).or(command){let a=a.action.clone();if a.ability_id.as_deref()==Some(b::HUNT){hunted=true;}eprintln!("natural turn {} actor0 {:?}",g.turn,a);t.action(0,a);}
  else if enemy.is_none(){let other=g.legal_actions(2).into_iter().find(|a|a.action.kind=="deploy");if let Some(a)=other{eprintln!("natural turn {} actor2 {:?}",g.turn,a.action);t.action(2,a.action);}else{t.pass();}}
  else{t.pass();}
 }
 if !done {let g=&t.room.game;eprintln!("natural terminal status={} turn={} window={:?} hunted={} assets={:?} hand={:?} core={:?} board={:?}",g.status,g.turn,g.window,hunted,g.players[0].assets.iter().map(|c|(&c.definition,c.exhausted)).collect::<Vec<_>>(),g.players[0].hand.iter().map(|c|&c.definition).collect::<Vec<_>>(),g.core_zones,g.regions.iter().flat_map(|r|r.cards.iter().map(|c|(&c.definition,c.controller,c.exhausted,c.lock_markers))).collect::<Vec<_>>());if let Ok(path)=std::env::var("BQ045_DEBUG_OUT"){std::fs::write(path,serde_json::to_vec_pretty(g).unwrap()).unwrap();}}
 assert!(done,"natural loop unfinished turn {}",t.room.game.turn);assert_eq!(t.room.game.players[0].honor,1);assert!(t.room.game.players[2].graveyard.iter().any(|c|c.definition=="JC125"));assert!(t.room.game.regions.iter().flat_map(|r|&r.cards).any(|c|c.definition=="TK010"&&c.exhausted));
 let mut v=trace_value(t);v["construction"]=serde_json::json!({"deck":deck,"seed":seed,"ordinaryCards":50,"separateCore":1,"minimumCommandCards":12,"privateRegistryOnly":true,"noLayoutOrResourceMutation":true});v
}
#[test]fn bq045_natural_and_prepared_actual_room_commands_export(){
 use crate::abi112_review_play_tests::Trace;let mut cases=vec![];let(g,s,t,v)=setup();let mut trace=Trace::new_preserving_rng(g,"bq045-prepared-hunt".into(),691);trace.action(0,hunt(&s,&t,&v));trace_finish(&mut trace,&v);cases.push(trace_value(trace));
 for (n,command) in ["BQ048","BQ063"].into_iter().enumerate(){let(mut g,_)=core(true);let v=field(&mut g,"JC125",2);g.regions[0].influence[1]=4;let spell=held(&mut g,command,0);let mut trace=Trace::new_preserving_rng(g,format!("bq045-prepared-{command}-core"),692+n);trace.action(0,Action{card_id:Some(spell),option:Some("core".into()),..Action::new("play")});trace_finish(&mut trace,&v);cases.push(trace_value(trace));}
 cases.push(natural());let mut bindings=crate::bq052_tests::source_bindings();use sha2::{Digest,Sha256};for(name,bytes)in[("rust-game/src/bq045.rs",include_bytes!("bq045.rs").as_slice()),("rust-game/src/bq045_tests.rs",include_bytes!("bq045_tests.rs").as_slice()),("rust-game/src/core_zone.rs",include_bytes!("core_zone.rs").as_slice()),("rust-game/src/bq048.rs",include_bytes!("bq048.rs").as_slice()),("rust-game/src/bq063.rs",include_bytes!("bq063.rs").as_slice())]{bindings["files"][name]=serde_json::json!(format!("{:x}",Sha256::digest(bytes)));}
 if let Ok(path)=std::env::var("BQ045_NATIVE_OUT"){std::fs::write(path,serde_json::to_vec_pretty(&serde_json::json!({"catalog":crate::catalog::catalog(),"sourceBindings":bindings,"cases":cases})).unwrap()).unwrap();}
}
